def compute(total, count):
    """
    Compute division with clean handling of zero division scenarios.

    Args:
        total: Numerator value
        count: Denominator value

    Returns:
        float: Division result, inf/-inf for division by zero with non-zero total,
               nan for division by zero with zero total
    """
    try:
        return total / count
    except ZeroDivisionError:
        # Handle division by zero based on total value
        if total > 0:
            return float('inf')
        elif total < 0:
            return float('-inf')
        else:
            return float('nan')
